package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager; import com.bedlessfighter.necroManager.managers.PermissionManager; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.jetbrains.annotations.NotNull; import java.util.List;
public final class WeatherCommand implements CommandExecutor,TabCompleter { public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String @NotNull [] a){if(a.length!=1||!List.of("clear","rain","thunder").contains(a[0].toLowerCase())){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /weather <clear|rain|thunder>");return true;}if(!PermissionManager.has(s,"necromanager.world")){MessageManager.send(s,"messages.no-perm","&cYou don't have enough permissions to issue this command!");return true;}if(!(s instanceof Player p)){MessageManager.send(s,"messages.player-required","&cConsole must specify a world (not supported yet).");return true;}String w=a[0].toLowerCase();p.getWorld().setStorm(!w.equals("clear"));p.getWorld().setThundering(w.equals("thunder"));p.getWorld().setWeatherDuration(12000);MessageManager.send(s,"messages.weather","&aWeather set to %weather%.",java.util.Map.of("weather",w));return true;}public List<String> onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String alias,@NotNull String @NotNull [] a){return a.length==1?List.of("clear","rain","thunder").stream().filter(v->v.startsWith(a[0].toLowerCase())).toList():List.of();} }